     1	/**
     2	 * The risk surcharges the office adds for a single insured item.
     3	 *
     4	 * A cursed item and a highly enchanted item each carry a risk surcharge on that item's
     5	 * own base premium, not on the premium of the whole policy. An item that is both carries
     6	 * both surcharges.
     7	 */
     8	public class ItemRiskSurcharge {
     9	
    10	    private final PriceList priceList = new PriceList();
    11	
    12	    public double forItem(Item item) {
    13	        double basePremium = priceList.basePremiumFor(item);
    14	        return basePremium * totalRateFor(item);
    15	    }
    16	
    17	    /**
    18	     * Each risk the office recognises is assessed on its own; an item that carries
    19	     * several risks carries the sum of their rates.
    20	     */
    21	    private double totalRateFor(Item item) {
    22	        double rate = 0;
    23	        for (RecognisedRisk risk : RecognisedRisk.values()) {
    24	            if (risk.isCarriedBy(item)) {
    25	                rate += risk.rate();
    26	            }
    27	        }
    28	        return rate;
    29	    }
    30	}
