     1	/**
     2	 * What the office pays out for an incident reported against a policy.
     3	 *
     4	 * The office settles an incident one damaged item at a time, and the incident's payout is
     5	 * what those settlements come to. The deductible is withheld per damage event, which is why
     6	 * it belongs to the single settlement and not to the tally.
     7	 */
     8	public class PayoutCalculator {
     9	
    10	    private static final int DEDUCTIBLE = 100;
    11	
    12	    private final ReimbursementClause reimbursementClause = new ReimbursementClause();
    13	
    14	    public int payoutFor(Incident incident, InsuredItems insuredItems) {
    15	        double payout = 0;
    16	        for (Damage damage : incident.damages()) {
    17	            payout += settlementFor(damage, insuredItems);
    18	        }
    19	        return OfficesFavour.onAmountPaidOut(payout);
    20	    }
    21	
    22	    /**
    23	     * What one damaged item is settled at: the damage the office reimburses under the
    24	     * clauses that cover it, less the deductible it withholds for every damage event.
    25	     */
    26	    private double settlementFor(Damage damage, InsuredItems insuredItems) {
    27	        return reimbursementClause.reimbursedAmountFor(damage, insuredItems.coveringItemFor(damage))
    28	                - DEDUCTIBLE;
    29	    }
    30	}
