     1	import java.util.List;
     2	
     3	/**
     4	 * Computes the premium for a quote, in the order the office assesses it.
     5	 *
     6	 * The policy base premium from the MHPCO price list comes first. The item-specific risk
     7	 * surcharges are then added on top of it, while the policy-wide modifiers are assessed
     8	 * against the base premium itself rather than against the surcharged amount. The
     9	 * processing fee is added at the very end, and only the final premium is rounded.
    10	 */
    11	public class PremiumCalculator {
    12	
    13	    private static final int PROCESSING_FEE = 5;
    14	
    15	    private final PolicyBasePremium policyBasePremiumRule = new PolicyBasePremium();
    16	    private final PolicyRiskSurcharges policyRiskSurcharges = new PolicyRiskSurcharges();
    17	    private final PolicyModifiers policyModifiers = new PolicyModifiers();
    18	
    19	    public int premiumFor(QuoteStep quoteStep, QuoteAssessment assessment) {
    20	        List<Item> items = quoteStep.items();
    21	        double policyBasePremium = policyBasePremiumRule.forItems(items);
    22	        double assessedPremium = policyBasePremium
    23	                + policyRiskSurcharges.forItems(items)
    24	                + policyModifiers.forPolicy(policyBasePremium, assessment);
    25	        return OfficesFavour.onAmountReceived(assessedPremium + PROCESSING_FEE);
    26	    }
    27	}
