     1	import java.util.List;
     2	
     3	/**
     4	 * The policy base premium: the sum of the base premiums of all insured items.
     5	 *
     6	 * The office prices alike items as a group, so that the building-block offer can apply
     7	 * to each group in turn; the policy base premium is the sum of those group prices.
     8	 * Risk surcharges for individual items are not part of it -- they attach to the
     9	 * affected item, not to the policy.
    10	 */
    11	public class PolicyBasePremium {
    12	
    13	    private final AlikeItems alikeItems = new AlikeItems();
    14	    private final ComponentBlockOffer blockOffer = new ComponentBlockOffer();
    15	
    16	    public double forItems(List<Item> items) {
    17	        double total = 0;
    18	        for (List<Item> group : alikeItems.groupsIn(items)) {
    19	            total += blockOffer.basePremiumFor(group);
    20	        }
    21	        return total;
    22	    }
    23	}
