     1	/**
     2	 * Rounding "in the MHPCO's favour": whichever way the fraction falls, the office keeps it.
     3	 *
     4	 * The favour is one rule with two directions, because the direction depends on which way the
     5	 * money flows. Money the office receives is rounded up; money the office pays out is rounded
     6	 * down. Stating both here keeps them from drifting apart.
     7	 */
     8	public final class OfficesFavour {
     9	
    10	    private OfficesFavour() {
    11	    }
    12	
    13	    /** An amount the customer pays the office, rounded up to whole G. */
    14	    public static int onAmountReceived(double amount) {
    15	        return (int) Math.ceil(amount);
    16	    }
    17	
    18	    /** An amount the office pays the customer, rounded down to whole G. */
    19	    public static int onAmountPaidOut(double amount) {
    20	        return (int) Math.floor(amount);
    21	    }
    22	}
===== PriceList.java =====
     1	import java.util.Map;
     2	import java.util.Set;
     3	
     4	/**
     5	 * The MHPCO price list: the base premium the office charges for a single insured item.
     6	 *
     7	 * The office prices two kinds of item differently. Each main item carries its own listed
     8	 * base premium. Components -- runes, moonstones -- are all priced at one uniform component
     9	 * rate, so a new component type joins the list without a price of its own.
    10	 *
    11	 * The list is also the office's statement of what it insures: a type the list does not
    12	 * name is a type the office does not cover, and asking its price is met with an objection.
    13	 * Membership and price are one fact per type, which is why they are kept together here --
    14	 * taking on a new line of business is a single new entry.
    15	 */
    16	public class PriceList {
    17	
    18	    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS = Map.of(
    19	            "sword", 100,
    20	            "amulet", 60,
    21	            "staff", 80,
    22	            "potion", 40);
    23	
    24	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    25	
    26	    private static final int COMPONENT_BASE_PREMIUM = 25;
    27	
    28	    public boolean isComponent(Item item) {
    29	        return COMPONENT_TYPES.contains(item.type());
    30	    }
    31	
    32	    public int basePremiumFor(Item item) {
    33	        if (isComponent(item)) {
    34	            return COMPONENT_BASE_PREMIUM;
    35	        }
    36	        if (!isMainItem(item)) {
    37	            throw new ClaimOfficeException("The office does not insure items of type " + item.type());
    38	        }
    39	        return MAIN_ITEM_BASE_PREMIUMS.get(item.type());
    40	    }
    41	
    42	    private boolean isMainItem(Item item) {
    43	        return MAIN_ITEM_BASE_PREMIUMS.containsKey(item.type());
    44	    }
    45	}

